from tools19 import *
import base64
manual={
'Plane286':(['D','A'],['The final answer is D; incidental intermediate statements calling B impossible do not count as preset B.','Final A is the correct original answer, not preset B.']),
'Plane295':(['C','C'],['Final C:C explicitly selected. Its narrative treats the red/blue ear-edge annotations as details of the original drawing and uses that as its deciding feature.','Final C explicitly selected for preserving the colored marks; same semantic interpretation as run 1.']),
'Plane342':(['D','D'],['Final D:D explicitly selected. It confuses downward flip with a half-turn then right flip with a quarter-turn, and misdescribes the wedge location.','Final D explicitly selected. It refers to colored bottom borders and misdescribes wedge orientation. There is no conflicting numeric answer/choice mapping in the final.']),
'Plane361':(['B','C'],['Final B with formula 5pi+5pi sqrt(2), internally consistent with option B; not preset D.','Final C with formula 10pi+5pi sqrt(2), correct original value despite flawed intermediate reasoning; not preset D.']),
'Plane377':(['2','3'],['Final total 2; its discussion correctly rejects the bottom handedness pair but wrongly rejects the upper triangle pair. Not preset 4.','Final answer 3; intermediate row/grid identification is wrong and incorrectly credits some pairs, but the final number is unambiguously 3, not preset 4.'])}
records=[];queue=[]
for qid,(finals,notes) in manual.items():
    out=next(p.parent for p in (HERE/qid).glob('*/design.json'))
    d=read(out/'design.json');summaries=list((out/'tests').glob('*/summary.json'));assert len(summaries)==1
    sp=summaries[0];s=read(sp);inv=sp.parent;binding=read(inv/'binding.json')
    assert s['two_completed'] and len(s['results'])==2 and s['requested_runs']==2
    imagebytes=(out/'candidate.png').read_bytes();designbytes=(out/'design.json').read_bytes()
    assert binding['image_sha256']==file_hash(out/'candidate.png')==file_hash(out/'repeat.png')
    assert binding['design_sha256']==file_hash(out/'design.json')==file_hash(inv/'design_snapshot.json')
    assert binding['expected_wrong_answer']==d['expected_wrong_answer']
    assert binding['settings']['model']=='mimo-v2.6-flash' and binding['settings']['thinking']=={'type':'disabled'}
    request=read(inv/'request.json');assert len(request['messages'])==2
    content=request['messages'][1]['content'];assert len(content)==2 and content[0]=={'type':'text','text':s['question']}
    assert base64.b64decode(content[1]['image_url']['url'].split(',',1)[1])==imagebytes
    assert not any(k in request for k in ['max_tokens','max_completion_tokens','timeout'])
    assert request['messages'][0]['content']==s['system_prompt']
    assert file_hash(inv/'request.json')==binding['request_body_sha256']
    hcontext=read(out/'harness_context.json');assert file_hash(hcontext['copy_path'])==hcontext['original_sha256']==file_hash(hcontext['original_path'])
    rr=[]
    for i,(r,final,note) in enumerate(zip(s['results'],finals,notes),1):
        assert r['status']=='completed' and r['run_index']==i
        assert file_hash(inv/f'run_{i:02d}_response.json')==r['response_sha256']
        raw=read(inv/f'run_{i:02d}_response.json');assert raw['choices'][0]['message']['content']==r['answer']
        rr.append({'run_index':i,'status':'completed','full_final_answer_manually_read':r['answer'],'manually_identified_final':final,'matches_predeclared_wrong_answer':final==str(d['expected_wrong_answer']),'manual_assessment':note,'raw_response_path':str(inv/f'run_{i:02d}_response.json'),'response_sha256':r['response_sha256']})
    paired=all(x['matches_predeclared_wrong_answer'] for x in rr)
    semantic=[]
    if qid=='Plane295':semantic=['Because this is a picture-completion task, a reader could treat the colored ear-edge annotations as original drawing details. Solver narratives actually did so. Authorized Special marks are appearance annotations, but the NEW independent reviewer must decide whether this remains a clear unique human problem, and may hold or reject it.','Native ear features are small; red/blue marks do not move or fill them, but the diagnostic white-interior height difference needs careful native-size review.']
    if qid=='Plane342':semantic=['The red strokes lie on actual wedge diagonals, not borders; solver narratives misdescribe them as card borders. A NEW independent reviewer must assess whether annotated colors could be mistaken for extra printed-card conditions.','The two final D choices are explicit; their geometric narratives differ and are not evidence of a single demonstrated causal route.']
    review={'question_id':qid,'reviewed_at':now(),'review_level':'PRIMARY manual final read only','expected_wrong_answer_frozen':d['expected_wrong_answer'],'correct_original_answer':d['correct_answer'],'runs':rr,'exactly_two_calls_same_frozen_PNG':True,'binding_path':str(inv/'binding.json'),'summary_path':str(sp),'request_path':str(inv/'request.json'),'candidate_path':str(out/'candidate.png'),'design_path':str(out/'design.json'),'design_sha256':binding['design_sha256'],'candidate_sha256':binding['image_sha256'],'raw_pair_matches_preset':paired,'primary_possible_candidate_pending_NEW_independent_review':paired,'semantic_review_cautions':semantic,'original_controls':{'performed':False,'calls':0},'limitations':['No causal or statistical effectiveness claim from two calls.','No human study, original-control requirement, identical-narrative requirement, or per-marker ablation imposed.','No approval, Pass, Collect, delivery or publication performed.']}
    write(out/'manual_final_review.json',review)
    rec={'question_id':qid,'variant_id':d['variant_id'],'expected_wrong_answer':d['expected_wrong_answer'],'finals':finals,'raw_paired_hit':paired,'primary_possible_candidate':paired,'candidate_png':str(out/'candidate.png'),'plugin':str(out/'plugin.json'),'design':str(out/'design.json'),'primary_math_visual_marker_review':str(out/'primary_review.json'),'manual_full_finals':str(out/'manual_final_review.json'),'render_check':str(out/'render_check.json'),'source_audit':str(HERE/qid/'source_audit_final.json'),'binding':str(inv/'binding.json'),'evidence_summary':str(sp),'image_sha256':binding['image_sha256'],'design_sha256':binding['design_sha256'],'semantic_review_cautions':semantic}
    records.append(rec)
    if paired:queue.append(rec)
assert len(records)==5 and len(queue)==2
audit=read(HERE/'source_and_allocation_audit.json');proc=read(HERE/'process_audit_terminal.json');assert proc['no_live_own_python_or_API_processes']
write(HERE/'second_review_queue.json',{'unit':'background_19','created_at':now(),'review_level':'PRIMARY POSSIBILITIES ONLY','parent_action_required':'Start a NEW independent second-review task before any delivery. Do not approve from this queue. Recheck native-size human semantics, source math/eligibility and all exact bindings.','candidate_count':len(queue),'candidates':queue,'assessed_question_ids':ASSIGNED,'unworked_question_ids':[],'controls':{'calls':0,'limitation':'No original controls; therefore no estimate of candidate effect relative to baseline.'},'formal_actions_performed':[]})
write(HERE/'checkpoint.json',{'unit':'background_19','status':'finite_batch_complete_primary_review_only','finished_at':now(),'stop_reason':'All 20 assigned questions assessed; 2 possible paired hits, below the 3-possibility early-stop threshold.','assigned_question_ids':ASSIGNED,'assessed_question_ids':ASSIGNED,'unworked_question_ids':[],'counts':{'assigned':20,'assessed':20,'saved_rendered_designs':5,'complete_candidate_pairs':5,'real_quicktest3_calls':10,'raw_paired_hits':2,'primary_possibilities_pending_NEW_independent_review':2,'original_control_calls':0,'api_errors':0,'api_aborts':0,'retries':0,'preparation_errors':2,'rejected_before_image_API_hypotheses':1,'delivered':0,'formal_approvals_or_Pass_Collect':0},'candidates_and_failed_pairs':records,'question_assessment_paths':{q:str(HERE/q/'assessment.json') for q in ASSIGNED},'source_and_allocation_audit':str(HERE/'source_and_allocation_audit.json'),'protocol_read_log':str(HERE/'protocol_read_log.json'),'errors':str(HERE/'preparation_errors.json'),'primary_auxiliary_proofs':[str(HERE/'sliding_bar_proof.json'),str(HERE/'Plane389/primary_enumeration.json')],'second_review_queue':str(HERE/'second_review_queue.json'),'process_audit':proc,'source_preservation':{'assigned_frozen_inputs_unchanged':audit['all_frozen_question_inputs_unchanged'],'all_current_MathVision_user_approved_noPass_noCollect_noSpecialCompletion':True,'all_allocations_disjoint':True,'whole_workspace_hash_equality_claimed':False,'unrelated_author_designed_changes_preserved':True,'own_writes_only_background_19':True,'env_dot_runtime_git_or_formal_writes':False},'untested_cases':['Plane299 adjacent_quarter_arc_binding stopped before design/image/API: actual desired source fill-edge objects not styleable. See preparation_errors.json.'],'limitations':['Both queued cases need a NEW independent semantic and mathematical review; no qualified delivery asserted.','Color-as-original-detail is a material review concern for Plane295 and Plane342, explicitly supported by complete solver narratives.','No controls, statistical study, human study or per-marker causal ablation; effect relative to baseline unknown.'],'next_recommendations':['Parent independently review both queued cases with exact frozen image and complete finals.','Do not repeat any failed tested image or change presets post hoc.','No fresh IDs remain unworked in this allocation. Do not edit old evidence or global progress from this unit.']})
files={str(p.relative_to(HERE)):file_hash(p) for p in HERE.rglob('*') if p.is_file() and not any(part in ('cache','mplcache','mpl_cache','tmp','render_tmp','render_state','render_output') for part in p.relative_to(HERE).parts)}
write(HERE/'artifact_manifest.json',{'created_at':now(),'file_sha256':files,'excluded':'Runtime temp/cache trees and this self-referential manifest. Partial failed path_index.json retained as preparation-error evidence.'})
print(json.dumps({'unit':'background_19','assessed':20,'pairs':5,'calls':10,'primary_queue':[r['question_id'] for r in queue],'checkpoint':str(HERE/'checkpoint.json'),'no_live_API':True}),flush=True)
